INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9191d078-d5ab-5941-81f9-5cb9cfc3e459', 'Germany German Corporate Governance Code 2017 Press Release', 'German Corporate Governance Code 2017 Press Release', 'This document is concerned with the 2017 amendments to the Corporate Governance Code in order to enhance transparency as the basis for stakeholders to assess corporate governance and to comply with international best practices in the German code for listed companies.', 'This document is concerned with the 2017 amendments to the Corporate Governance Code in order to enhance transparency as the basis for stakeholders to assess corporate governance and to comply with international best practices in the German code for listed companies.', 'This document is concerned with the 2017 amendments to the Corporate Governance Code in order to enhance transparency as the basis for stakeholders to assess corporate governance and to comply with international best practices in the German code for listed companies.', 'Germany', 'climate', 'in_force', '2017-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_20', ARRAY['other sustainability policy', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
