INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eeee1874-296e-5ead-9198-f0af9f4e1d7a', 'Germany Valuing the Benefits, Costs and Impacts of Ecosystem-based', 'Valuing the Benefits, Costs and Impacts of Ecosystem-based Adaptation Measures', 'This sourcebook addresses the topic of EbA valuation. It offers a resource to guide the design, delivery and use of EbA valuation studies to inform and influence decision-making.', 'This sourcebook addresses the topic of EbA valuation. It offers a resource to guide the design, delivery and use of EbA valuation studies to inform and influence decision-making.', 'This sourcebook addresses the topic of EbA valuation. It offers a resource to guide the design, delivery and use of EbA valuation studies to inform and influence decision-making.', 'Germany', 'climate', 'in_force', '2017-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_70', ARRAY['sdg2', 'sdg13', 'sdg14', 'germany', 'other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2a22af28-a27f-53ae-8a4d-38258baf6231', 'Germany Green and Inclusive Business Toolbox', 'Green and Inclusive Business Toolbox', 'This document aims to provide planning officers, project leaders and staff involved in private sector development and other sector projects with a set of tried-and-tested tools that can be used to integrate a GIB perspective and GIB models into existing or future German development cooperation programmes.', 'This document aims to provide planning officers, project leaders and staff involved in private sector development and other sector projects with a set of tried-and-tested tools that can be used to integrate a GIB perspective and GIB models into existing or future German development cooperation programmes.', 'This document aims to provide planning officers, project leaders and staff involved in private sector development and other sector projects with a set of tried-and-tested tools that can be used to integrate a GIB perspective and GIB models into existing or future German development cooperation programmes.', 'Germany', 'governance', 'in_force', '2017-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_71', ARRAY['other sustainability policy', 'germany', 'sdg17', 'mandatory', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9c0edc8a-7773-5254-963f-4a3a65be3b0a', 'Germany Sustainability Code Benchmarking sustainable business', 'The Sustainability Code Benchmarking sustainable business', 'The German Sustainability Code (DNK) serves as a voluntary reporting framework designed to enhance corporate transparency and accountability in sustainability practices. Developed by the German Council for Sustainable Development, it aligns with the European Union''s CSR Directive Implementation Act and supports businesses in preparing non-financial disclosures. The Code encompasses 20 criteria grouped into four categories: Strategy, Process Management, Environment, and Society. It offers practical guidelines to integrate sustainability into governance, decision-making, and reporting. By aligning with international frameworks such as GRI, ISO 26000, and the Paris Agreement, the DNK facilitates compatibility and comparability across sectors and jurisdictions. The Code is intended for companies of all sizes, providing a flexible "comply or explain" approach, enabling businesses to either disclose sustainability-related information or justify omissions. It aims to foster sustainable development by guiding organizations in addressing material sustainability aspects, including environmental impacts, human rights, and anti-corruption measures.', 'The German Sustainability Code (DNK) serves as a voluntary reporting framework designed to enhance corporate transparency and accountability in sustainability practices. Developed by the German Council for Sustainable Development, it aligns with the European Union''s CSR Directive Implementation Act and supports businesses in preparing non-financial disclosures. The Code encompasses 20 criteria grouped into four categories: Strategy, Process Management, Environment, and Society. It offers practical guidelines to integrate sustainability into governance, decision-making, and reporting. By aligning with international frameworks such as GRI, ISO 26000, and the Paris Agreement, the DNK facilitates compatibility and comparability across sectors and jurisdictions. The Code is intended for companies of all sizes, providing a flexible "comply or explain" approach, enabling businesses to either disclose sustainability-related information or justify omissions. It aims to foster sustainable development by guiding organizations in addressing material sustainability aspects, including environmental impacts, human rights, and anti-corruption measures.', 'The German Sustainability Code (DNK) serves as a voluntary reporting framework designed to enhance corporate transparency and accountability in sustainability practices. Developed by the German Council for Sustainable Development, it aligns with the European Union''s CSR Directive Implementation Act and supports businesses in preparing non-financial disclosures. The Code encompasses 20 criteria grouped into four categories: Strategy, Process Management, Environment, and Society. It offers practical guidelines to integrate sustainability into governance, decision-making, and reporting. By aligning with international frameworks such as GRI, ISO 26000, and the Paris Agreement, the DNK facilitates compatibility and comparability across sectors and jurisdictions. The Code is intended for companies of all sizes, providing a flexible "comply or explain" approach, enabling businesses to either disclose sustainability-related information or justify omissions. It aims to foster sustainable development by guiding organizations in addressing material sustainability aspects, including environmental impacts, human rights, and anti-corruption measures.', 'Germany', 'climate', 'in_force', '2017-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_8', ARRAY['sdg13', 'germany', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('97e02004-808f-51d1-a4ca-ca56e13b387f', 'Germany Climate Action Plan 2050: Principles and goals', 'Climate Action Plan 2050: Principles and goals of the German government''s climate policy', 'The "Climate Action Plan 2050" serves as a comprehensive strategy for Germany''s long-term climate goals, aligned with the Paris Agreement''s targets of achieving greenhouse gas neutrality by the second half of the century. It establishes sector-specific targets for reducing emissions, with a milestone of at least a 55% reduction by 2030 compared to 1990 levels. The plan emphasizes a holistic transformation across energy, transport, industry, agriculture, and forestry sectors. Key measures include advancing renewable energy, improving energy efficiency, fostering innovation, and supporting structural changes in affected regions. The document also underscores the importance of integrating climate action with economic and social policies to ensure sustainable development and public acceptance.', 'The "Climate Action Plan 2050" serves as a comprehensive strategy for Germany''s long-term climate goals, aligned with the Paris Agreement''s targets of achieving greenhouse gas neutrality by the second half of the century. It establishes sector-specific targets for reducing emissions, with a milestone of at least a 55% reduction by 2030 compared to 1990 levels. The plan emphasizes a holistic transformation across energy, transport, industry, agriculture, and forestry sectors. Key measures include advancing renewable energy, improving energy efficiency, fostering innovation, and supporting structural changes in affected regions. The document also underscores the importance of integrating climate action with economic and social policies to ensure sustainable development and public acceptance.', 'The "Climate Action Plan 