INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3b00d29c-6b42-528e-a9cb-41b720a4fbdd', 'Germany Insurance Supervision Act', 'Insurance Supervision Act', 'The German Insurance Supervision Act of 2015 focuses on regulating insurance undertakings to ensure financial stability and consumer protection. It outlines requirements for authorization, risk management, reporting obligations, prevention of money laundering, and cross-border business activities. The policy targets companies operating in the insurance industry, emphasizing solvency, financial adequacy, and compliance with European Economic Area standards. It is a mandatory disclosure type policy.', 'The German Insurance Supervision Act of 2015 focuses on regulating insurance undertakings to ensure financial stability and consumer protection. It outlines requirements for authorization, risk management, reporting obligations, prevention of money laundering, and cross-border business activities. The policy targets companies operating in the insurance industry, emphasizing solvency, financial adequacy, and compliance with European Economic Area standards. It is a mandatory disclosure type policy.', 'The German Insurance Supervision Act of 2015 focuses on regulating insurance undertakings to ensure financial stability and consumer protection. It outlines requirements for authorization, risk management, reporting obligations, prevention of money laundering, and cross-border business activities. The policy targets companies operating in the insurance industry, emphasizing solvency, financial adequacy, and compliance with European Economic Area standards. It is a mandatory disclosure type policy.', 'Germany', 'climate', 'in_force', '2015-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_10', ARRAY['germany', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('50a0c52b-0c25-5b58-94b3-09559d737489', 'Germany German Corporate Governance Code', 'German Corporate Governance Code 2015', 'The German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. Its purpose is to promote the trust of international and national investors, customers, employees and the general public in the management and supervision of listed German stock corporations.', 'The German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. Its purpose is to promote the trust of international and national investors, customers, employees and the general public in the management and supervision of listed German stock corporations.', 'The German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. Its purpose is to promote the trust of international and national investors, customers, employees and the general public in the management and supervision of listed German stock corporations.', 'Germany', 'governance', 'in_force', '2015-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_2', ARRAY['germany', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
