INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('892a5590-feba-52df-bf59-730608f34f1d', 'Germany Indicators for Managing Ecosystem Services – Options &', 'Indicators for Managing Ecosystem Services – Options & Examples', 'Guidance for seeking information that supports the integration of ecosystem services into policy and public management.', 'Guidance for seeking information that supports the integration of ecosystem services into policy and public management.', 'Guidance for seeking information that supports the integration of ecosystem services into policy and public management.', 'Germany', 'climate', 'in_force', '2015-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_69', ARRAY['guidance_frameworks', 'sdg13', 'sdg14', 'germany', 'sdg2', 'other sustainability policy', 'mandatory', 'sdg6', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3f7953c3-5a82-59b1-8a32-df4769bd6ce5', 'Germany German Sustainability Code', 'Guideline for the German Sustainability Code', 'The "Guideline for the German Sustainability Code" (GSC) is a framework designed to facilitate corporate sustainability reporting for companies, particularly small and medium-sized enterprises (SMEs). Developed by the German Council for Sustainable Development, it emphasizes transparency and comparability in sustainability practices through a structured reporting process. The GSC includes 20 criteria divided into four sections: Strategy, Process Management, Environment, and Society. These criteria guide organizations in aligning their operations with sustainability objectives, addressing key areas such as materiality, resource management, human rights, and stakeholder engagement. The guideline encourages using international standards like the GRI and UN Global Compact and focuses on simplifying complex reporting requirements for better accessibility and adoption by diverse businesses.', 'The "Guideline for the German Sustainability Code" (GSC) is a framework designed to facilitate corporate sustainability reporting for companies, particularly small and medium-sized enterprises (SMEs). Developed by the German Council for Sustainable Development, it emphasizes transparency and comparability in sustainability practices through a structured reporting process. The GSC includes 20 criteria divided into four sections: Strategy, Process Management, Environment, and Society. These criteria guide organizations in aligning their operations with sustainability objectives, addressing key areas such as materiality, resource management, human rights, and stakeholder engagement. The guideline encourages using international standards like the GRI and UN Global Compact and focuses on simplifying complex reporting requirements for better accessibility and adoption by diverse businesses.', 'The "Guideline for the German Sustainability Code" (GSC) is a framework designed to facilitate corporate sustainability reporting for companies, particularly small and medium-sized enterprises (SMEs). Developed by the German Council for Sustainable Development, it emphasizes transparency and comparability in sustainability practices through a structured reporting process. The GSC includes 20 criteria divided into four sections: Strategy, Process Management, Environment, and Society. These criteria guide organizations in aligning their operations with sustainability objectives, addressing key areas such as materiality, resource management, human rights, and stakeholder engagement. The guideline encourages using international standards like the GRI and UN Global Compact and focuses on simplifying complex reporting requirements for better accessibility and adoption by diverse businesses.', 'Germany', 'climate', 'in_force', '2014-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_4', ARRAY['guidance_frameworks', 'other sustainability policy', 'germany', 'sdg17', 'sdg16', 'sdg12', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
