INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('44ace160-d818-5b15-9161-40ec1f7b86ec', 'Germany Communicating sustainability. Seven recommendations for issuers', 'Communicating sustainability. Seven recommendations for issuers', '"Communicating Sustainability: Seven Recommendations for Issuers" is a strategic guide developed by Deutsche Börse Group in collaboration with key financial and sustainability organizations. The document aims to assist companies of all sizes in integrating Environmental, Social, and Governance (ESG) considerations into their capital market communication. It consolidates best practices and focuses on aligning corporate sustainability reporting with the requirements of investors and analysts. The guide emphasizes voluntary adoption and provides practical recommendations structured around seven core principles: senior management leadership, stakeholder-centric materiality, risk-return focus, preference for quantitative data, adherence to standards, and attention to presentation. By addressing these principles, companies can improve their disclosure effectiveness, meet investor needs, and foster informed investment decisions.', '"Communicating Sustainability: Seven Recommendations for Issuers" is a strategic guide developed by Deutsche Börse Group in collaboration with key financial and sustainability organizations. The document aims to assist companies of all sizes in integrating Environmental, Social, and Governance (ESG) considerations into their capital market communication. It consolidates best practices and focuses on aligning corporate sustainability reporting with the requirements of investors and analysts. The guide emphasizes voluntary adoption and provides practical recommendations structured around seven core principles: senior management leadership, stakeholder-centric materiality, risk-return focus, preference for quantitative data, adherence to standards, and attention to presentation. By addressing these principles, companies can improve their disclosure effectiveness, meet investor needs, and foster informed investment decisions.', '"Communicating Sustainability: Seven Recommendations for Issuers" is a strategic guide developed by Deutsche Börse Group in collaboration with key financial and sustainability organizations. The document aims to assist companies of all sizes in integrating Environmental, Social, and Governance (ESG) considerations into their capital market communication. It consolidates best practices and focuses on aligning corporate sustainability reporting with the requirements of investors and analysts. The guide emphasizes voluntary adoption and provides practical recommendations structured around seven core principles: senior management leadership, stakeholder-centric materiality, risk-return focus, preference for quantitative data, adherence to standards, and attention to presentation. By addressing these principles, companies can improve their disclosure effectiveness, meet investor needs, and foster informed investment decisions.', 'Germany', 'climate', 'in_force', '2013-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_3', ARRAY['guidance_frameworks', 'other sustainability policy', 'germany', 'sdg7', 'sdg17', 'sdg16', 'sdg9', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
