INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5ac121cb-10c4-5e11-901b-00eb2c02f9ab', 'Germany National Strategy for Corporate Social Responsibility (CSR Action', 'National Strategy for Corporate Social Responsibility (CSR Action Plan) of German Federal Government', 'This document outlines the German Action Plan for CSR. Its objective is to increase the number of enterprises that recognise and use social responsibility to shape their business strategies in accordance with the principle of sustainable development because socially and environmentally proactive business practices can bring enterprises advantages in the national and international arena.', 'This document outlines the German Action Plan for CSR. Its objective is to increase the number of enterprises that recognise and use social responsibility to shape their business strategies in accordance with the principle of sustainable development because socially and environmentally proactive business practices can bring enterprises advantages in the national and international arena.', 'This document outlines the German Action Plan for CSR. Its objective is to increase the number of enterprises that recognise and use social responsibility to shape their business strategies in accordance with the principle of sustainable development because socially and environmentally proactive business practices can bring enterprises advantages in the national and international arena.', 'Germany', 'climate', 'in_force', '2010-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_1', ARRAY['sdg13', 'other sustainability policy', 'germany', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
