INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d4ba1897-a477-580d-8749-458ffdd48051', 'Germany Law to simplify waste control', 'Law to simplify waste control', 'The German Law to simplify waste control, enacted in 2006, aims to regulate waste management processes, including sampling, storage, and disposal. It outlines obligations for waste producers, owners, and disposal companies to adhere to specific requirements and procedures. The law implements guidelines from EU directives on waste management and environmental impact assessment. It emphasizes promoting circular economy objectives and ensuring proper waste disposal. This mandatory disclosure policy targets companies involved in waste management, transportation, and disposal.', 'The German Law to simplify waste control, enacted in 2006, aims to regulate waste management processes, including sampling, storage, and disposal. It outlines obligations for waste producers, owners, and disposal companies to adhere to specific requirements and procedures. The law implements guidelines from EU directives on waste management and environmental impact assessment. It emphasizes promoting circular economy objectives and ensuring proper waste disposal. This mandatory disclosure policy targets companies involved in waste management, transportation, and disposal.', 'The German Law to simplify waste control, enacted in 2006, aims to regulate waste management processes, including sampling, storage, and disposal. It outlines obligations for waste producers, owners, and disposal companies to adhere to specific requirements and procedures. The law implements guidelines from EU directives on waste management and environmental impact assessment. It emphasizes promoting circular economy objectives and ensuring proper waste disposal. This mandatory disclosure policy targets companies involved in waste management, transportation, and disposal.', 'Germany', 'climate', 'in_force', '2006-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_35', ARRAY['germany', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
