INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('faef94d0-206d-5aca-ac39-feaf247c9a53', 'Germany Amendment to the German Corporate Governance Code', 'Amendment to the German Corporate Governance Code - The Cromme Code (June 2005)', 'This German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. It clarifies the rights of shareholders, who provide the company with the required equity capital and who carry the entrepreneurial risk.', 'This German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. It clarifies the rights of shareholders, who provide the company with the required equity capital and who carry the entrepreneurial risk.', 'This German Corporate Governance Code (the "Code") presents essential statutory regulations for the management and supervision (governance) of German listed companies and contains internationally and nationally recognized standards for good and responsible governance. It clarifies the rights of shareholders, who provide the company with the required equity capital and who carry the entrepreneurial risk.', 'Germany', 'governance', 'in_force', '2005-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_12', ARRAY['germany', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
