INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea2e7662-4516-5b6b-8b3a-7c399be41fed', 'Germany German Government Panel on Corporate Governance Summary of', 'German Government Panel on Corporate Governance Summary of Recommendations', 'The Report makes nearly 150 recommendations for amendments or changes to existing provisions of German law and also sets forth proposals on how the German corporate governance system should be further developed in order to maintain a normative framework that is suitable and attractive not only for companies, but also for domestic and foreign investors.', 'The Report makes nearly 150 recommendations for amendments or changes to existing provisions of German law and also sets forth proposals on how the German corporate governance system should be further developed in order to maintain a normative framework that is suitable and attractive not only for companies, but also for domestic and foreign investors.', 'The Report makes nearly 150 recommendations for amendments or changes to existing provisions of German law and also sets forth proposals on how the German corporate governance system should be further developed in order to maintain a normative framework that is suitable and attractive not only for companies, but also for domestic and foreign investors.', 'Germany', 'climate', 'in_force', '2001-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_15', ARRAY['guidance_frameworks', 'germany', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('206728f5-cfc0-5704-a9e2-5723c34c642d', 'Germany Corporate Governance Rules for German Quoted Companies', 'Corporate Governance Rules for German Quoted Companies 2000', 'The Rules of the Code serve as general guidelines for Corporate Governance of quoted German companies. Quoted companies are all enterprises whose shares are officially listed on a German stock exchange or traded over-the-counter.', 'The Rules of the Code serve as general guidelines for Corporate Governance of quoted German companies. Quoted companies are all enterprises whose shares are officially listed on a German stock exchange or traded over-the-counter.', 'The Rules of the Code serve as general guidelines for Corporate Governance of quoted German companies. Quoted companies are all enterprises whose shares are officially listed on a German stock exchange or traded over-the-counter.', 'Germany', 'governance', 'in_force', '2000-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_17', ARRAY['guidance_frameworks', 'germany', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22aa0e30-2b4d-559b-ab74-9be8584667ef', 'Germany German Code of Corporate Governance (GCCG)', 'German Code of Corporate Governance (GCCG) 2000', 'This code contains recommendations for the arrangement of a regulatory framework which is intended to promote the quality of company management. These recommendations are based on the consideration that in a globalized economy, the circumstances of successful company management admittedly come closer together.', 'This code contains recommendations for the arrangement of a regulatory framework which is intended to promote the quality of company management. These recommendations are based on the consideration that in a globalized economy, the circumstances of successful company management admittedly come closer together.', 'This code contains recommendations for the arrangement of a regulatory framework which is intended to promote the quality of company management. These recommendations are based on the consideration that in a globalized economy, the circumstances of successful company management admittedly come closer together.', 'Germany', 'governance', 'in_force', '2000-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_18', ARRAY['germany', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('fe4e594a-ea4c-5aa3-8162-ee1d4d83063d', 'Germany Control and Transparency Act in the corporate sector', 'Control and Transparency Act in the corporate sector (KonTraG)', 'The Control and Transparency Act in the corporate sector (KonTraG) was passed in Germany in 1998 with the main purpose of enhancing control and transparency in stock exchange-listed companies. The Act introduces amendments to the Stock Corporation Act, focusing on shareholder rights, stock exchange regulations, and corporate governance practices. This mandatory disclosure policy aims to improve accountability, prevent fraud, and protect investors'' interests by setting clear guidelines for corporate behavior and financial reporting.', 'The Control and Transparency Act in the corporate sector (KonTraG) was passed in Germany in 1998 with the main purpose of enhancing control and transparency in stock exchange-listed companies. The Act introduces amendments to the Stock Corporation Act, focusing on shareholder rights, stock exchange regulations, and corporate governance practices. This mandatory disclosure policy aims to improve accountability, prevent fraud, and protect investors'' interests by setting clear guidelines for corporate behavior and financial reporting.', 'The Control and Transparency Act in the corporate sector (KonTraG) was passed in Germany in 1998 with the main purpose of enhancing control and transparency in stock exchange-listed companies. The Act introduces amendments to the Stock Corporation Act, focusing on shareholder rights, stock exchange regulations, and corporate governance practices. This mandatory disclosure policy aims to improve accountability, prevent fraud, and protect investors'' interests by setting clear guidelines for corporate behavior and financial reporting.', 'Germany', 'climate', 'in_force', '1998-01-01'::date, 'Germany', 'https://www.carrotsandsticks.org/policies/63_27', ARRAY['germany', 'regulations', 'mandatory', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2a829714-301a-5dd2-a30f-db5e6107097d', 'Ghana ESG Disclosures Guidance Manual', 'ESG Disclosures Guidance Manual', 'The focus of this document is to guide how listed companies in Ghana and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards in sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management. This document is also available as a guide to other organisations that might be interested in ESG integration and reporting.', 'The focus of this document is to guide how listed companies in Ghana and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards in sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management. This document is also available as a guide to other organisations that might be interested in ESG integration and reporting.', 'The focus of this document is to guide how listed companies in Ghana and other organisations interested in ESG reporting can collect, analyse, and publicly disclose important ESG information using an approach that meets international standards in sustainability reporting. This document can also act a guide on how to progressively integrate ESG in strategy, operations, and performance management. This document is also available as a guide to other organisations that might be interested in ESG integration and reporting.', 'Ghana', 'climate', 'in_force', '2022-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_15', ARRAY['guidance_frameworks', 'sdg7', 'mandatory', 'disclosure', 'sdg9', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb1b19ab-21cc-58a3-8325-0aa19bd29ddc', 'Ghana Corporate Governance Code for Listed Companies 2020 SEC/CD/001/', 'The Corporate Governance Code for Listed Companies 2020 SEC/CD/001/10/2020', 'The Corporate Governance Code for Listed Companies 2020 is a set of guidelines developed by the Securities and Exchange Commission of Ghana to promote good corporate governance practices among listed companies in Ghana. The code provides a framework for companies to ensure effective board oversight, transparent and ethical management practices, and appropriate risk management. The code covers several key areas, including board composition and structure, the roles and responsibilities of the board, shareholder rights and engagement, transparency and disclosure, and internal controls and risk management. The code is designed to be flexible, allowing companies to tailor their approach to their specific circumstances and priorities. The aim of the code is to improve the quality of corporate governance among listed companies in Ghana and promote sustainable growth and development in the country. The code is mandatory for all listed companies in Ghana, and failure to comply with the code can result in penalties or sanctions by the Securities and Exchange Commission.', 'The Corporate Governance Code for Listed Companies 2020 is a set of guidelines developed by the Securities and Exchange Commission of Ghana to promote good corporate governance practices among listed companies in Ghana. The code provides a framework for companies to ensure effective board oversight, transparent and ethical management practices, and appropriate risk management. The code covers several key areas, including board composition and structure, the roles and responsibilities of the board, shareholder rights and engagement, transparency and disclosure, and internal controls and risk management. The code is designed to be flexible, allowing companies to tailor their approach to their specific circumstances and priorities. The aim of the code is to improve the quality of corporate governance among listed companies in Ghana and promote sustainable growth and development in the country. The code is mandatory for all listed companies in Ghana, and failure to comply with the code can result in penalties or sanctions by the Securities and Exchange Commission.', 'The Corporate Governance Code for Listed Companies 2020 is a set of guidelines developed by the Securities and Exchange Commission of Ghana to promote good corporate governance practices among listed companies in Ghana. The code provides a framework for companies to ensure effective board oversight, transparent and ethical management practices, and appropriate risk management. The code covers several key areas, including board composition and structure, the roles and responsibilities of the board, shareholder rights and engagement, transparency and disclosure, and internal controls and risk management. The code is designed to be flexible, allowing companies to tailor their approach to their specific circumstances and priorities. The aim of the code is to improve the quality of corporate governance among listed companies in Ghana and promote sustainable growth and development in the country. The code is mandatory for all listed companies in Ghana, and failure to comply with the code can result in penalties or sanctions by the Securities and Exchange Commission.', 'Ghana', 'governance', 'in_force', '2020-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_16', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8168707f-d3bd-547c-b240-7fba3f3aaf41', 'Ghana Sustainable Banking Principles and Sector Guidance Notes', 'Sustainable Banking Principles and Sector Guidance Notes', 'The Sustainable Banking Principles and Sector Guidance Notes 2019 is a set of guidelines developed by the Bank of Ghana to promote sustainable and responsible banking practices in Ghana. The principles provide a framework for banks to integrate environmental, social, and governance (ESG) considerations into their business operations, risk management, and decision-making processes. The guidance notes provide detailed guidance on how to implement the principles and specific areas of ESG risk and opportunity that banks should consider. The Sustainable Banking Principles and Sector Guidance Notes are designed to be voluntary and flexible, allowing banks to tailor their approach to their specific circumstances and priorities. They are also aligned with international best practices, including the United Nations Sustainable Development Goals and the Equator Principles.', 'The Sustainable Banking Principles and Sector Guidance Notes 2019 is a set of guidelines developed by the Bank of Ghana to promote sustainable and responsible banking practices in Ghana. The principles provide a framework for banks to integrate environmental, social, and governance (ESG) considerations into their business operations, risk management, and decision-making processes. The guidance notes provide detailed guidance on how to implement the principles and specific areas of ESG risk and opportunity that banks should consider. The Sustainable Banking Principles and Sector Guidance Notes are designed to be voluntary and flexible, allowing banks to tailor their approach to their specific circumstances and priorities. They are also aligned with international best practices, including the United Nations Sustainable Development Goals and the Equator Principles.', 'The Sustainable Banking Principles and Sector Guidance Notes 2019 is a set of guidelines developed by the Bank of Ghana to promote sustainable and responsible banking practices in Ghana. The principles provide a framework for banks to integrate environmental, social, and governance (ESG) considerations into their business operations, risk management, and decision-making processes. The guidance notes provide detailed guidance on how to implement the principles and specific areas of ESG risk and opportunity that banks should consider. The Sustainable Banking Principles and Sector Guidance Notes are designed to be voluntary and flexible, allowing banks to tailor their approach to their specific circumstances and priorities. They are also aligned with international best practices, including the United Nations Sustainable Development Goals and the Equator Principles.', 'Ghana', 'climate', 'in_force', '2019-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_14', ARRAY['guidance_frameworks', 'sdg2', 'sdg9', 'sdg7', 'sdg16', 'disclosure', 'sdg15', 'voluntary', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('47f7f0e2-e74f-5ab2-bc37-1a4da7782cd2', 'Ghana Corporate Governance Directive 2018 - For Banks, Savings', 'Corporate Governance Directive 2018 - For Banks, Savings and Loans Companies , Finance Houses and Financial Holding Companies', 'The objectives of this directive are a) to require Regulated Financial Institutions to adopt sound corporate governance principles and best practices to enable them under take their licensed business in a sustainable manner, b) to promote the interest of depositors and other stakeholders by enhancing corporate performance and accountability of the Regulated Financial Institutions and c) to promote and maintain public trust and confidence in Regulated Financial Institutions by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole.', 'The objectives of this directive are a) to require Regulated Financial Institutions to adopt sound corporate governance principles and best practices to enable them under take their licensed business in a sustainable manner, b) to promote the interest of depositors and other stakeholders by enhancing corporate performance and accountability of the Regulated Financial Institutions and c) to promote and maintain public trust and confidence in Regulated Financial Institutions by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole.', 'The objectives of this directive are a) to require Regulated Financial Institutions to adopt sound corporate governance principles and best practices to enable them under take their licensed business in a sustainable manner, b) to promote the interest of depositors and other stakeholders by enhancing corporate performance and accountability of the Regulated Financial Institutions and c) to promote and maintain public trust and confidence in Regulated Financial Institutions by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole.', 'Ghana', 'governance', 'in_force', '2018-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_1', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('477f324d-64b9-583a-86c4-c71310f46f72', 'Ghana Banking Business - Corporate Governance Directive', 'The Banking Business - Corporate Governance Directive 2018', 'The objectives of this directive is a) to require regulated financial institution to adopt sound corporate governance principles and best practices to enable them to perform their role in enhancing economic growth in Ghana; b) to promote and maintain public trust and confidence in regulated financial institution by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole; and c) Minimise the possibility of regulated financial institution failures that are usually rooted in poor corporate governance practices.', 'The objectives of this directive is a) to require regulated financial institution to adopt sound corporate governance principles and best practices to enable them to perform their role in enhancing economic growth in Ghana; b) to promote and maintain public trust and confidence in regulated financial institution by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole; and c) Minimise the possibility of regulated financial institution failures that are usually rooted in poor corporate governance practices.', 'The objectives of this directive is a) to require regulated financial institution to adopt sound corporate governance principles and best practices to enable them to perform their role in enhancing economic growth in Ghana; b) to promote and maintain public trust and confidence in regulated financial institution by prescribing sound corporate governance standards which are critical to the proper functioning of the banking sector and the economy as a whole; and c) Minimise the possibility of regulated financial institution failures that are usually rooted in poor corporate governance practices.', 'Ghana', 'governance', 'in_force', '2018-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_4', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('517e69f7-4f60-592c-83af-753fecc49e6d', 'Ghana Continuing Listing Requirements', 'Continuing Listing Requirements, 2018', 'The Continuing Listing Requirements, 2018 policy from Ghana outlines obligations for listed companies, including immediate announcements to prevent false markets, disclosure of dividends, meeting notices, and changes in company structure. It mandates quarterly reports to the Securities and Exchange Commission and submission of annual reports in line with regulations. Companies must provide detailed information on directors'' holdings, material contracts, shareholding analysis, and key stakeholders. The policy enforces timely securities allotment, transfers, and registrations. It aims to ensure transparency, market integrity, and accountability among listed companies.', 'The Continuing Listing Requirements, 2018 policy from Ghana outlines obligations for listed companies, including immediate announcements to prevent false markets, disclosure of dividends, meeting notices, and changes in company structure. It mandates quarterly reports to the Securities and Exchange Commission and submission of annual reports in line with regulations. Companies must provide detailed information on directors'' holdings, material contracts, shareholding analysis, and key stakeholders. The policy enforces timely securities allotment, transfers, and registrations. It aims to ensure transparency, market integrity, and accountability among listed companies.', 'The Continuing Listing Requirements, 2018 policy from Ghana outlines obligations for listed companies, including immediate announcements to prevent false markets, disclosure of dividends, meeting notices, and changes in company structure. It mandates quarterly reports to the Securities and Exchange Commission and submission of annual reports in line with regulations. Companies must provide detailed information on directors'' holdings, material contracts, shareholding analysis, and key stakeholders. The policy enforces timely securities allotment, transfers, and registrations. It aims to ensure transparency, market integrity, and accountability among listed companies.', 'Ghana', 'climate', 'in_force', '2018-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_5', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0ee56ac4-d5ec-5afd-a48b-7816d863467a', 'Ghana Draft Corporate Governance Code for Listed Companies', 'Draft Corporate Governance Code for Listed Companies', 'This Code applies to all companies whose securities are admitted to trading on the Ghana Stock Exchange.', 'This Code applies to all companies whose securities are admitted to trading on the Ghana Stock Exchange.', 'This Code applies to all companies whose securities are admitted to trading on the Ghana Stock Exchange.', 'Ghana', 'governance', 'in_force', '2018-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_7', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('78ef87e3-f98f-55d1-b087-ca4a689f2e16', 'Ghana Biodiversity Offsetting Guidelines', 'Biodiversity Offsetting Guidelines', 'This guideline is intended to serve as guidance to offset providers and undertakings on the requirements/considerations in the offset scheme. It explains the benefits of participating in the Biodiversity Offset Business Scheme (BOBS), how to calculate the amount of biodiversity credits needed to offset an impact, and different ways to source the credits from offset providers and also create an Offset.', 'This guideline is intended to serve as guidance to offset providers and undertakings on the requirements/considerations in the offset scheme. It explains the benefits of participating in the Biodiversity Offset Business Scheme (BOBS), how to calculate the amount of biodiversity credits needed to offset an impact, and different ways to source the credits from offset providers and also create an Offset.', 'This guideline is intended to serve as guidance to offset providers and undertakings on the requirements/considerations in the offset scheme. It explains the benefits of participating in the Biodiversity Offset Business Scheme (BOBS), how to calculate the amount of biodiversity credits needed to offset an impact, and different ways to source the credits from offset providers and also create an Offset.', 'Ghana', 'climate', 'in_force', '2016-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_11', ARRAY['guidance_frameworks', 'sdg2', 'other sustainability policy', 'sdg9', 'sdg15', 'voluntary', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('351c2956-915d-5172-98ff-d71341b164bf', 'Mandatory Disclosure items for public companies in Ghana', 'Mandatory Disclosure items for public companies in Ghana', 'The Guideline makes the disclosure of the under listed items mandatory in Ghana for Public Companies in line with international best practice. The mandatory disclosure items contained in this Guideline are in addition to the disclosure requirements in the Companies Act, 1963 (Act 179) and any other disclosure requirements under the International Financial Reporting Standards (IFRS).', 'The Guideline makes the disclosure of the under listed items mandatory in Ghana for Public Companies in line with international best practice. The mandatory disclosure items contained in this Guideline are in addition to the disclosure requirements in the Companies Act, 1963 (Act 179) and any other disclosure requirements under the International Financial Reporting Standards (IFRS).', 'The Guideline makes the disclosure of the under listed items mandatory in Ghana for Public Companies in line with international best practice. The mandatory disclosure items contained in this Guideline are in addition to the disclosure requirements in the Companies Act, 1963 (Act 179) and any other disclosure requirements under the International Financial Reporting Standards (IFRS).', 'Ghana', 'climate', 'in_force', '2016-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_8', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dd841818-f8d5-5041-b80f-040064d82eaf', 'Ghana Hazardous and electronic waste control and management act', 'Hazardous and electronic waste control and management act', 'This document is concerned with an act to provide for the control, management and disposal of hazardous waste, electrical and electronic waste for related purposes.', 'This document is concerned with an act to provide for the control, management and disposal of hazardous waste, electrical and electronic waste for related purposes.', 'This document is concerned with an act to provide for the control, management and disposal of hazardous waste, electrical and electronic waste for related purposes.', 'Ghana', 'climate', 'in_force', '2016-01-01'::date, 'Ghana', 'https://www.carrotsandsticks.org/policies/64_9', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'sdg9', 'ghana']::text[]) ON CONFLICT (id) DO NOTHING;
